pub struct NoopWlShmListener {}

pub fn (mut listener NoopWlShmListener) format(_proxy WlShm, _format u32) {
}

struct WlShmSink {
mut:
	proxy    WlShm
	listener WlShmListener = NoopWlShmListener{}
}

fn (mut s WlShmSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			format := msg.arg_u32(0)!
			s.listener.format(s.proxy, format)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_shm events.
pub fn (proxy &WlShm) set_listener(listener WlShmListener) ! {
	proxy.conn.set_sink(proxy.id, WlShmSink{
		proxy:    *proxy
		listener: listener
	})!
}

// Create a new wl_shm_pool object. The pool can be used to create shared
// memory based buffer objects. The server will mmap size bytes of the passed
// file descriptor, to use as backing memory for the pool.
pub fn (proxy &WlShm) create_pool(fd int, size i32) !WlShmPool {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_shm_pool'
	}
	proxy.conn.register_object(id_id, 'wl_shm_pool', &wl_shm_pool_desc)!
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(wayland.ObjectRef{ id: id_id }),
		wayland.ArgValue(wayland.Fd{ fd: fd }), wayland.ArgValue(size)])!
	return WlShmPool{
		Object: id_object
	}
}

// Using this request a client can tell the server that it is not going to
// use the shm object anymore. Objects created via this interface remain
// unaffected.
pub fn (proxy &WlShm) release() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

