// WlBuffer is a client side proxy for wl_buffer.
// A buffer provides the content for a wl_surface. Buffers are created
// through factory interfaces such as wl_shm, wp_linux_buffer_params (from
// the linux-dmabuf protocol extension) or similar. It has a width and a
// height and can be attached to a wl_surface, but the mechanism by which a
// client provides and updates the contents is defined by the buffer factory
// interface. Color channels are assumed to be electrical rather than optical
// (in other words, encoded with a transfer function) unless otherwise
// specified. If the buffer uses a format that has an alpha channel, the
// alpha channel is assumed to be premultiplied into the electrical color
// channel values (after transfer function encoding) unless otherwise
// specified. Note, because wl_buffer objects are created from multiple
// independent factory interfaces, the wl_buffer interface is frozen at
// version 1.
pub struct WlBuffer {
	wayland.Object
}

// wl_buffer_proxy wraps an object id in a WlBuffer proxy.
pub fn wl_buffer_proxy(conn &wayland.Connection, id u32) WlBuffer {
	return WlBuffer{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_buffer'
		}
	}
}

// WlBufferListener receives the events of a wl_buffer object.
pub interface WlBufferListener {
	// Sent when this wl_buffer is no longer used by the compositor. For more
	// information on when release events may or may not be sent, and what
	// consequences it has, please see the description of wl_surface.attach. If a
	// client receives a release event before the frame callback requested in the
	// same wl_surface.commit that attaches this wl_buffer to a surface, then the
	// client is immediately free to reuse the buffer and its backing storage,
	// and does not need a second buffer for the next surface content update.
	// Typically this is possible, when the compositor maintains a copy of the
	// wl_surface contents, e.g. as a GL texture. This is an important
	// optimization for GL(ES) compositors with wl_shm clients.
mut:
	release(proxy WlBuffer)
}

// NoopWlBufferListener ignores every wl_buffer event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlBufferListener {}

pub fn (mut listener NoopWlBufferListener) release(_proxy WlBuffer) {
}

struct WlBufferSink {
mut:
	proxy    WlBuffer
	listener WlBufferListener = NoopWlBufferListener{}
}

fn (mut s WlBufferSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			s.listener.release(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_buffer events.
pub fn (proxy &WlBuffer) set_listener(listener WlBufferListener) ! {
	proxy.conn.set_sink(proxy.id, WlBufferSink{
		proxy:    *proxy
		listener: listener
	})!
}

// Destroy a buffer. If and how you need to release the backing storage is
// defined by the buffer factory interface. For possible side-effects to a
// surface, see wl_surface.attach.
pub fn (proxy &WlBuffer) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

