// WlDataOffer is a client side proxy for wl_data_offer.
// A wl_data_offer represents a piece of data offered for transfer by another
// client (the source client). It is used by the copy-and-paste and
// drag-and-drop mechanisms. The offer describes the different mime types
// that the data can be converted to and provides the mechanism for
// transferring the data directly from the source client.
pub struct WlDataOffer {
	wayland.Object
}

// wl_data_offer_proxy wraps an object id in a WlDataOffer proxy.
pub fn wl_data_offer_proxy(conn &wayland.Connection, id u32) WlDataOffer {
	return WlDataOffer{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_data_offer'
		}
	}
}

// WlDataOfferListener receives the events of a wl_data_offer object.
pub interface WlDataOfferListener {
	// Sent immediately after creating the wl_data_offer object. One event per
	// offered mime type.
mut:
	offer(proxy WlDataOffer, mime_type string)
	// This event indicates the actions offered by the data source. It will be
	// sent immediately after creating the wl_data_offer object, or anytime the
	// source side changes its offered actions through
	// wl_data_source.set_actions.
	source_actions(proxy WlDataOffer, source_actions u32)
	// This event indicates the action selected by the compositor after matching
	// the source/destination side actions. Only one action (or none) will be
	// offered here. This event can be emitted multiple times during the
	// drag-and-drop operation in response to destination side action changes
	// through wl_data_offer.set_actions. This event will no longer be emitted
	// after wl_data_device.drop happened on the drag-and-drop destination, the
	// client must honor the last action received, or the last preferred one set
	// through wl_data_offer.set_actions when handling an "ask" action.
	// Compositors may also change the selected action on the fly, mainly in
	// response to keyboard modifier changes during the drag-and-drop operation.
	// The most recent action received is always the valid one. Prior to
	// receiving wl_data_device.drop, the chosen action may change (e.g. due to
	// keyboard modifiers being pressed). At the time of receiving
	// wl_data_device.drop the drag-and-drop destination must honor the last
	// action received. Action changes may still happen after
	// wl_data_device.drop, especially on "ask" actions, where the drag-and-drop
	// destination may choose another action afterwards. Action changes happening
	// at this stage are always the result of inter-client negotiation, the
	// compositor shall no longer be able to induce a different action. Upon
	// "ask" actions, it is expected that the drag-and-drop destination may
	// potentially choose a different action and/or mime type, based on
	// wl_data_offer.source_actions and finally chosen by the user (e.g. popping
	// up a menu with the available options). The final wl_data_offer.set_actions
	// and wl_data_offer.accept requests must happen before the call to
	// wl_data_offer.finish.
	action(proxy WlDataOffer, dnd_action u32)
}

// NoopWlDataOfferListener ignores every wl_data_offer event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlDataOfferListener {}

pub fn (mut listener NoopWlDataOfferListener) offer(_proxy WlDataOffer, _mime_type string) {
}

pub fn (mut listener NoopWlDataOfferListener) source_actions(_proxy WlDataOffer, _source_actions u32) {
}

pub fn (mut listener NoopWlDataOfferListener) action(_proxy WlDataOffer, _dnd_action u32) {
}

struct WlDataOfferSink {
mut:
	proxy    WlDataOffer
	listener WlDataOfferListener = NoopWlDataOfferListener{}
}

fn (mut s WlDataOfferSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			mime_type := msg.arg_string(0)!
			s.listener.offer(s.proxy, mime_type)
		}
		1 {
			source_actions := msg.arg_u32(0)!
			s.listener.source_actions(s.proxy, source_actions)
		}
		2 {
			dnd_action := msg.arg_u32(0)!
			s.listener.action(s.proxy, dnd_action)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_data_offer events.
pub fn (proxy &WlDataOffer) set_listener(listener WlDataOfferListener) ! {
	proxy.conn.set_sink(proxy.id, WlDataOfferSink{
		proxy:    *proxy
		listener: listener
	})!
}

// Indicate that the client can accept the given mime type, or NULL for not
// accepted. For objects of version 2 or older, this request is used by the
// client to give feedback whether the client can receive the given mime
// type, or NULL if none is accepted; the feedback does not determine whether
// the drag-and-drop operation succeeds or not. For objects of version 3 or
// newer, this request determines the final result of the drag-and-drop
// operation. If the end result is that no mime types were accepted, the
// drag-and-drop operation will be cancelled and the corresponding drag
// source will receive wl_data_source.cancelled. Clients may still use this
// event in conjunction with wl_data_source.action for feedback.
pub fn (proxy &WlDataOffer) accept(serial u32, mime_type string) ! {
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(serial), wayland.ArgValue(mime_type)])!
}

// To transfer the offered data, the client issues this request and indicates
// the mime type it wants to receive. The transfer happens through the passed
// file descriptor (typically created with the pipe system call). The source
// client writes the data in the mime type representation requested and then
// closes the file descriptor. The receiving client reads from the read end
// of the pipe until EOF and then closes its end, at which point the transfer
// is complete. This request may happen multiple times for different mime
// types, both before and after wl_data_device.drop. Drag-and-drop
// destination clients may preemptively fetch data or examine it more closely
// to determine acceptance.
pub fn (proxy &WlDataOffer) receive(mime_type string, fd int) ! {
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(mime_type),
		wayland.ArgValue(wayland.Fd{ fd: fd })])!
}

// Destroy the data offer.
pub fn (proxy &WlDataOffer) destroy() ! {
	proxy.conn.request(proxy.id, 2, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Notifies the compositor that the drag destination successfully finished
// the drag-and-drop operation. Upon receiving this request, the compositor
// will emit wl_data_source.dnd_finished on the drag source client. It is a
// client error to perform other requests than wl_data_offer.destroy after
// this one. It is also an error to perform this request after a NULL mime
// type has been set in wl_data_offer.accept or no action was received
// through wl_data_offer.action. If wl_data_offer.finish request is received
// for a non drag and drop operation, the invalid_finish protocol error is
// raised.
pub fn (proxy &WlDataOffer) finish() ! {
	proxy.conn.request(proxy.id, 3, []wayland.ArgValue{})!
}

// Sets the actions that the destination side client supports for this
// operation. This request may trigger the emission of wl_data_source.action
// and wl_data_offer.action events if the compositor needs to change the
// selected action. This request can be called multiple times throughout the
// drag-and-drop operation, typically in response to wl_data_device.enter or
// wl_data_device.motion events. This request determines the final result of
// the drag-and-drop operation. If the end result is that no action is
// accepted, the drag source will receive wl_data_source.cancelled. The
// dnd_actions argument must contain only values expressed in the
// wl_data_device_manager.dnd_actions enum, and the preferred_action argument
// must only contain one of those values set, otherwise it will result in a
// protocol error. While managing an "ask" action, the destination
// drag-and-drop client may perform further wl_data_offer.receive requests,
// and is expected to perform one last wl_data_offer.set_actions request with
// a preferred action other than "ask" (and optionally wl_data_offer.accept)
// before requesting wl_data_offer.finish, in order to convey the action
// selected by the user. If the preferred action is not in the
// wl_data_offer.source_actions mask, an error will be raised. If the "ask"
// action is dismissed (e.g. user cancellation), the client is expected to
// perform wl_data_offer.destroy right away. This request can only be made on
// drag-and-drop offers, a protocol error will be raised otherwise.
pub fn (proxy &WlDataOffer) set_actions(dnd_actions u32, preferred_action u32) ! {
	proxy.conn.request(proxy.id, 4, [wayland.ArgValue(dnd_actions), wayland.ArgValue(preferred_action)])!
}

// wl_data_offer.error: values of the wl_data_offer protocol enum.
// finish request was called untimely
pub const wl_data_offer_error_invalid_finish = u32(0)
// action mask contains invalid values
pub const wl_data_offer_error_invalid_action_mask = u32(1)
// action argument has an invalid value
pub const wl_data_offer_error_invalid_action = u32(2)
// offer doesn't accept this request
pub const wl_data_offer_error_invalid_offer = u32(3)

