// WlDataSource is a client side proxy for wl_data_source.
// The wl_data_source object is the source side of a wl_data_offer. It is
// created by the source client in a data transfer and provides a way to
// describe the offered data and a way to respond to requests to transfer the
// data.
pub struct WlDataSource {
	wayland.Object
}

// wl_data_source_proxy wraps an object id in a WlDataSource proxy.
pub fn wl_data_source_proxy(conn &wayland.Connection, id u32) WlDataSource {
	return WlDataSource{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_data_source'
		}
	}
}

// WlDataSourceListener receives the events of a wl_data_source object.
pub interface WlDataSourceListener {
	// Sent when a target accepts pointer_focus or motion events. If a target
	// does not accept any of the offered types, type is NULL. Used for feedback
	// during drag-and-drop.
mut:
	target(proxy WlDataSource, mime_type string)
	// Request for data from the client. Send the data as the specified mime type
	// over the passed file descriptor, then close it.
	send(proxy WlDataSource, mime_type string, fd int)
	// This data source is no longer valid. There are several reasons why this
	// could happen: - The data source has been replaced by another data source.
	// - The drag-and-drop operation was performed, but the drop destination did
	// not accept any of the mime types offered through wl_data_source.target. -
	// The drag-and-drop operation was performed, but the drop destination did
	// not select any of the actions present in the mask offered through
	// wl_data_source.action. - The drag-and-drop operation was performed but
	// didn't happen over a surface. - The compositor cancelled the drag-and-drop
	// operation (e.g. compositor dependent timeouts to avoid stale drag-and-drop
	// transfers). The client should clean up and destroy this data source. For
	// objects of version 2 or older, wl_data_source.cancelled will only be
	// emitted if the data source was replaced by another data source.
	cancelled(proxy WlDataSource)
	// The user performed the drop action. This event does not indicate
	// acceptance, wl_data_source.cancelled may still be emitted afterwards if
	// the drop destination does not accept any mime type. However, this event
	// might not be received if the compositor cancelled the drag-and-drop
	// operation before this event could happen. Note that the data_source may
	// still be used in the future and should not be destroyed here.
	dnd_drop_performed(proxy WlDataSource)
	// The drop destination finished interoperating with this data source, so the
	// client is now free to destroy this data source and free all associated
	// data. If the action used to perform the operation was "move", the source
	// can now delete the transferred data.
	dnd_finished(proxy WlDataSource)
	// This event indicates the action selected by the compositor after matching
	// the source/destination side actions. Only one action (or none) will be
	// offered here. This event can be emitted multiple times during the
	// drag-and-drop operation, mainly in response to destination side changes
	// through wl_data_offer.set_actions, and as the data device enters/leaves
	// surfaces. It is only possible to receive this event after
	// wl_data_source.dnd_drop_performed if the drag-and-drop operation ended in
	// an "ask" action, in which case the final wl_data_source.action event will
	// happen immediately before wl_data_source.dnd_finished. Compositors may
	// also change the selected action on the fly, mainly in response to keyboard
	// modifier changes during the drag-and-drop operation. The most recent
	// action received is always the valid one. The chosen action may change
	// alongside negotiation (e.g. an "ask" action can turn into a "move"
	// operation), so the effects of the final action must always be applied in
	// wl_data_source.dnd_finished. Clients can trigger cursor surface changes
	// from this point, so they reflect the current action.
	action(proxy WlDataSource, dnd_action u32)
}

// NoopWlDataSourceListener ignores every wl_data_source event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlDataSourceListener {}

pub fn (mut listener NoopWlDataSourceListener) target(_proxy WlDataSource, _mime_type string) {
}

pub fn (mut listener NoopWlDataSourceListener) send(_proxy WlDataSource, _mime_type string, _fd int) {
}

pub fn (mut listener NoopWlDataSourceListener) cancelled(_proxy WlDataSource) {
}

pub fn (mut listener NoopWlDataSourceListener) dnd_drop_performed(_proxy WlDataSource) {
}

pub fn (mut listener NoopWlDataSourceListener) dnd_finished(_proxy WlDataSource) {
}

pub fn (mut listener NoopWlDataSourceListener) action(_proxy WlDataSource, _dnd_action u32) {
}

struct WlDataSourceSink {
mut:
	proxy    WlDataSource
	listener WlDataSourceListener = NoopWlDataSourceListener{}
}

fn (mut s WlDataSourceSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			mime_type := msg.arg_string(0)!
			s.listener.target(s.proxy, mime_type)
		}
		1 {
			mime_type := msg.arg_string(0)!
			fd := msg.arg_fd(1)!
			s.listener.send(s.proxy, mime_type, fd)
		}
		2 {
			s.listener.cancelled(s.proxy)
		}
		3 {
			s.listener.dnd_drop_performed(s.proxy)
		}
		4 {
			s.listener.dnd_finished(s.proxy)
		}
		5 {
			dnd_action := msg.arg_u32(0)!
			s.listener.action(s.proxy, dnd_action)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_data_source events.
pub fn (proxy &WlDataSource) set_listener(listener WlDataSourceListener) ! {
	proxy.conn.set_sink(proxy.id, WlDataSourceSink{
		proxy:    *proxy
		listener: listener
	})!
}

// This request adds a mime type to the set of mime types advertised to
// targets. Can be called several times to offer multiple types.
pub fn (proxy &WlDataSource) offer(mime_type string) ! {
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(mime_type)])!
}

// Destroy the data source.
pub fn (proxy &WlDataSource) destroy() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Sets the actions that the source side client supports for this operation.
// This request may trigger wl_data_source.action and wl_data_offer.action
// events if the compositor needs to change the selected action. The
// dnd_actions argument must contain only values expressed in the
// wl_data_device_manager.dnd_actions enum, otherwise it will result in a
// protocol error. This request must be made once only, and can only be made
// on sources used in drag-and-drop, so it must be performed before
// wl_data_device.start_drag. Attempting to use the source other than for
// drag-and-drop will raise a protocol error.
pub fn (proxy &WlDataSource) set_actions(dnd_actions u32) ! {
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(dnd_actions)])!
}

