// WlDataDevice is a client side proxy for wl_data_device.
// There is one wl_data_device per seat which can be obtained from the global
// wl_data_device_manager singleton. A wl_data_device provides access to
// inter-client data transfer mechanisms such as copy-and-paste and
// drag-and-drop.
pub struct WlDataDevice {
	wayland.Object
}

// wl_data_device_proxy wraps an object id in a WlDataDevice proxy.
pub fn wl_data_device_proxy(conn &wayland.Connection, id u32) WlDataDevice {
	return WlDataDevice{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_data_device'
		}
	}
}

// WlDataDeviceListener receives the events of a wl_data_device object.
pub interface WlDataDeviceListener {
	// The data_offer event introduces a new wl_data_offer object, which will
	// subsequently be used in either the data_device.enter event (for
	// drag-and-drop) or the data_device.selection event (for selections).
	// Immediately following the data_device.data_offer event, the new data_offer
	// object will send out data_offer.offer events to describe the mime types it
	// offers.
mut:
	data_offer(proxy WlDataDevice, id WlDataOffer)
	// This event is sent when an active drag-and-drop pointer enters a surface
	// owned by the client. The position of the pointer at enter time is provided
	// by the x and y arguments, in surface-local coordinates.
	enter(proxy WlDataDevice, serial u32, surface WlSurface, x f64, y f64, id ?WlDataOffer)
	// This event is sent when the drag-and-drop pointer leaves the surface and
	// the session ends. The client must destroy the wl_data_offer introduced at
	// enter time at this point.
	leave(proxy WlDataDevice)
	// This event is sent when the drag-and-drop pointer moves within the
	// currently focused surface. The new position of the pointer is provided by
	// the x and y arguments, in surface-local coordinates.
	motion(proxy WlDataDevice, time u32, x f64, y f64)
	// The event is sent when a drag-and-drop operation is ended because the
	// implicit grab is removed. The drag-and-drop destination is expected to
	// honor the last action received through wl_data_offer.action, if the
	// resulting action is "copy" or "move", the destination can still perform
	// wl_data_offer.receive requests, and is expected to end all transfers with
	// a wl_data_offer.finish request. If the resulting action is "ask", the
	// action will not be considered final. The drag-and-drop destination is
	// expected to perform one last wl_data_offer.set_actions request, or
	// wl_data_offer.destroy in order to cancel the operation.
	drop(proxy WlDataDevice)
	// The selection event is sent out to notify the client of a new
	// wl_data_offer for the selection for this device. The
	// data_device.data_offer and the data_offer.offer events are sent out
	// immediately before this event to introduce the data offer object. The
	// selection event is sent to a client immediately before receiving keyboard
	// focus and when a new selection is set while the client has keyboard focus.
	// The data_offer is valid until a new data_offer or NULL is received or
	// until the client loses keyboard focus. Switching surface with keyboard
	// focus within the same client doesn't mean a new selection will be sent.
	// The client must destroy the previous selection data_offer, if any, upon
	// receiving this event.
	selection(proxy WlDataDevice, id ?WlDataOffer)
}

// NoopWlDataDeviceListener ignores every wl_data_device event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlDataDeviceListener {}

pub fn (mut listener NoopWlDataDeviceListener) data_offer(_proxy WlDataDevice, _id WlDataOffer) {
}

pub fn (mut listener NoopWlDataDeviceListener) enter(_proxy WlDataDevice, _serial u32, _surface WlSurface, _x f64, _y f64, _id ?WlDataOffer) {
}

pub fn (mut listener NoopWlDataDeviceListener) leave(_proxy WlDataDevice) {
}

pub fn (mut listener NoopWlDataDeviceListener) motion(_proxy WlDataDevice, _time u32, _x f64, _y f64) {
}

pub fn (mut listener NoopWlDataDeviceListener) drop(_proxy WlDataDevice) {
}

pub fn (mut listener NoopWlDataDeviceListener) selection(_proxy WlDataDevice, _id ?WlDataOffer) {
}

struct WlDataDeviceSink {
mut:
	proxy    WlDataDevice
	listener WlDataDeviceListener = NoopWlDataDeviceListener{}
}

fn (mut s WlDataDeviceSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			id_id := msg.arg_id(0)!
			s.proxy.conn.register_object(id_id, 'wl_data_offer', &wl_data_offer_desc)!
			id := wl_data_offer_proxy(s.proxy.conn, id_id)
			s.listener.data_offer(s.proxy, id)
		}
		1 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			x := msg.arg_fixed(2)!.f64()
			y := msg.arg_fixed(3)!.f64()
			id_id := msg.arg_id(4)!
			mut id := ?WlDataOffer(none)
			if id_id != 0 {
				id = wl_data_offer_proxy(s.proxy.conn, id_id)
			}
			s.listener.enter(s.proxy, serial, surface, x, y, id)
		}
		2 {
			s.listener.leave(s.proxy)
		}
		3 {
			time := msg.arg_u32(0)!
			x := msg.arg_fixed(1)!.f64()
			y := msg.arg_fixed(2)!.f64()
			s.listener.motion(s.proxy, time, x, y)
		}
		4 {
			s.listener.drop(s.proxy)
		}
		5 {
			id_id := msg.arg_id(0)!
			mut id := ?WlDataOffer(none)
			if id_id != 0 {
				id = wl_data_offer_proxy(s.proxy.conn, id_id)
			}
			s.listener.selection(s.proxy, id)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_data_device events.
pub fn (proxy &WlDataDevice) set_listener(listener WlDataDeviceListener) ! {
	proxy.conn.set_sink(proxy.id, WlDataDeviceSink{
		proxy:    *proxy
		listener: listener
	})!
}

// This request asks the compositor to start a drag-and-drop operation on
// behalf of the client. The source argument is the data source that provides
// the data for the eventual data transfer. If source is NULL, enter, leave
// and motion events are sent only to the client that initiated the drag and
// the client is expected to handle the data passing internally. If source is
// destroyed, the drag-and-drop session will be cancelled. The origin surface
// is the surface where the drag originates and the client must have an
// active implicit grab that matches the serial. The icon surface is an
// optional (can be NULL) surface that provides an icon to be moved around
// with the cursor. Initially, the top-left corner of the icon surface is
// placed at the cursor hotspot, but subsequent wl_surface.offset requests
// can move the relative position. Attach requests must be confirmed with
// wl_surface.commit as usual. The icon surface is given the role of a
// drag-and-drop icon. If the icon surface already has another role, it
// raises a protocol error. The input region is ignored for wl_surfaces with
// the role of a drag-and-drop icon. The given source may not be used in any
// further set_selection or start_drag requests. Attempting to reuse a
// previously-used source may send a used_source error.
pub fn (proxy &WlDataDevice) start_drag(source ?WlDataSource, origin WlSurface, icon ?WlSurface, serial u32) ! {
	source_id := if value := source { value.id } else { u32(0) }
	icon_id := if value := icon { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 0, [
		wayland.ArgValue(wayland.ObjectRef{ id: source_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: origin.id }),
		wayland.ArgValue(wayland.ObjectRef{ id: icon_id }),
		wayland.ArgValue(serial),
	])!
}

// This request asks the compositor to set the selection to the data from the
// source on behalf of the client. To unset the selection, set the source to
// NULL. The given source may not be used in any further set_selection or
// start_drag requests. Attempting to reuse a previously-used source may send
// a used_source error.
pub fn (proxy &WlDataDevice) set_selection(source ?WlDataSource, serial u32) ! {
	source_id := if value := source { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 1, [
		wayland.ArgValue(wayland.ObjectRef{ id: source_id }),
		wayland.ArgValue(serial),
	])!
}

// This request destroys the data device.
pub fn (proxy &WlDataDevice) release() ! {
	proxy.conn.request(proxy.id, 2, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

