// WlDataDeviceManager is a client side proxy for wl_data_device_manager.
// The wl_data_device_manager is a singleton global object that provides
// access to inter-client data transfer mechanisms such as copy-and-paste and
// drag-and-drop. These mechanisms are tied to a wl_seat and this interface
// lets a client get a wl_data_device corresponding to a wl_seat. Depending
// on the version bound, the objects created from the bound
// wl_data_device_manager object will have different requirements for
// functioning properly. See wl_data_source.set_actions, wl_data_offer.accept
// and wl_data_offer.finish for details.
pub struct WlDataDeviceManager {
	wayland.Object
}

// wl_data_device_manager_proxy wraps an object id in a WlDataDeviceManager proxy.
pub fn wl_data_device_manager_proxy(conn &wayland.Connection, id u32) WlDataDeviceManager {
	return WlDataDeviceManager{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_data_device_manager'
		}
	}
}

// Create a new data source.
pub fn (proxy &WlDataDeviceManager) create_data_source() !WlDataSource {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_data_source'
	}
	proxy.conn.register_object(id_id, 'wl_data_source', &wl_data_source_desc)!
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(wayland.ObjectRef{ id: id_id })])!
	return WlDataSource{
		Object: id_object
	}
}

// Create a new data device for a given seat.
pub fn (proxy &WlDataDeviceManager) get_data_device(seat WlSeat) !WlDataDevice {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_data_device'
	}
	proxy.conn.register_object(id_id, 'wl_data_device', &wl_data_device_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: id_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id })])!
	return WlDataDevice{
		Object: id_object
	}
}

// This request destroys the wl_data_device_manager. This has no effect on
// any other objects.
pub fn (proxy &WlDataDeviceManager) release() ! {
	proxy.conn.request(proxy.id, 2, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

