pub interface WlShellSurfaceListener {
	// Ping a client to check if it is receiving events and sending requests. A
	// client is expected to reply with a pong request.
mut:
	ping(proxy WlShellSurface, serial u32)
	// The configure event asks the client to resize its surface. The size is a
	// hint, in the sense that the client is free to ignore it if it doesn't
	// resize, pick a smaller size (to satisfy aspect ratio or resize in steps of
	// NxM pixels). The edges parameter provides a hint about how the surface was
	// resized. The client may use this information to decide how to adjust its
	// content to the new size (e.g. a scrolling area might adjust its content
	// position to leave the viewable content unmoved). The client is free to
	// dismiss all but the last configure event it received. The width and height
	// arguments specify the size of the window in surface-local coordinates.
	configure(proxy WlShellSurface, edges u32, width i32, height i32)
	// The popup_done event is sent out when a popup grab is broken, that is,
	// when the user clicks a surface that doesn't belong to the client owning
	// the popup surface.
	popup_done(proxy WlShellSurface)
}

// NoopWlShellSurfaceListener ignores every wl_shell_surface event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlShellSurfaceListener {}

pub fn (mut listener NoopWlShellSurfaceListener) ping(_proxy WlShellSurface, _serial u32) {
}

pub fn (mut listener NoopWlShellSurfaceListener) configure(_proxy WlShellSurface, _edges u32, _width i32, _height i32) {
}

pub fn (mut listener NoopWlShellSurfaceListener) popup_done(_proxy WlShellSurface) {
}

struct WlShellSurfaceSink {
mut:
	proxy    WlShellSurface
	listener WlShellSurfaceListener = NoopWlShellSurfaceListener{}
}

fn (mut s WlShellSurfaceSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			serial := msg.arg_u32(0)!
			s.listener.ping(s.proxy, serial)
		}
		1 {
			edges := msg.arg_u32(0)!
			width := msg.arg_int(1)!
			height := msg.arg_int(2)!
			s.listener.configure(s.proxy, edges, width, height)
		}
		2 {
			s.listener.popup_done(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_shell_surface events.
pub fn (proxy &WlShellSurface) set_listener(listener WlShellSurfaceListener) ! {
	proxy.conn.set_sink(proxy.id, WlShellSurfaceSink{
		proxy:    *proxy
		listener: listener
	})!
}

// A client must respond to a ping event with a pong request or the client
// may be deemed unresponsive.
pub fn (proxy &WlShellSurface) pong(serial u32) ! {
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(serial)])!
}

// Start a pointer-driven move of the surface. This request must be used in
// response to a button press event. The server may ignore move requests
// depending on the state of the surface (e.g. fullscreen or maximized).
pub fn (proxy &WlShellSurface) move(seat WlSeat, serial u32) ! {
	proxy.conn.request(proxy.id, 1, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
	])!
}

// Start a pointer-driven resizing of the surface. This request must be used
// in response to a button press event. The server may ignore resize requests
// depending on the state of the surface (e.g. fullscreen or maximized).
pub fn (proxy &WlShellSurface) resize(seat WlSeat, serial u32, edges u32) ! {
	proxy.conn.request(proxy.id, 2, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
		wayland.ArgValue(edges),
	])!
}

// Map the surface as a toplevel surface. A toplevel surface is not
// fullscreen, maximized or transient.
pub fn (proxy &WlShellSurface) set_toplevel() ! {
	proxy.conn.request(proxy.id, 3, []wayland.ArgValue{})!
}

// Map the surface relative to an existing surface. The x and y arguments
// specify the location of the upper left corner of the surface relative to
// the upper left corner of the parent surface, in surface-local coordinates.
// The flags argument controls details of the transient behaviour.
pub fn (proxy &WlShellSurface) set_transient(parent WlSurface, x i32, y i32, flags u32) ! {
	proxy.conn.request(proxy.id, 4, [
		wayland.ArgValue(wayland.ObjectRef{ id: parent.id }),
		wayland.ArgValue(x),
		wayland.ArgValue(y),
		wayland.ArgValue(flags),
	])!
}

// Map the surface as a fullscreen surface. If an output parameter is given
// then the surface will be made fullscreen on that output. If the client
// does not specify the output then the compositor will apply its policy -
// usually choosing the output on which the surface has the biggest surface
// area. The client may specify a method to resolve a size conflict between
// the output size and the surface size - this is provided through the method
// parameter. The framerate parameter is used only when the method is set to
// "driver", to indicate the preferred framerate. A value of 0 indicates that
// the client does not care about framerate. The framerate is specified in
// mHz, that is framerate of 60000 is 60Hz. A method of "scale" or "driver"
// implies a scaling operation of the surface, either via a direct scaling
// operation or a change of the output mode. This will override any kind of
// output scaling, so that mapping a surface with a buffer size equal to the
// mode can fill the screen independent of buffer_scale. A method of "fill"
// means we don't scale up the buffer, however any output scale is applied.
// This means that you may run into an edge case where the application maps a
// buffer with the same size of the output mode but buffer_scale 1 (thus
// making a surface larger than the output). In this case it is allowed to
// downscale the results to fit the screen. The compositor must reply to this
// request with a configure event with the dimensions for the output on which
// the surface will be made fullscreen.
pub fn (proxy &WlShellSurface) set_fullscreen(method u32, framerate u32, output ?WlOutput) ! {
	output_id := if value := output { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 5, [wayland.ArgValue(method), wayland.ArgValue(framerate),
		wayland.ArgValue(wayland.ObjectRef{ id: output_id })])!
}

// Map the surface as a popup. A popup surface is a transient surface with an
// added pointer grab. An existing implicit grab will be changed to
// owner-events mode, and the popup grab will continue after the implicit
// grab ends (i.e. releasing the mouse button does not cause the popup to be
// unmapped). The popup grab continues until the window is destroyed or a
// mouse button is pressed in any other client's window. A click in any of
// the client's surfaces is reported as normal, however, clicks in other
// clients' surfaces will be discarded and trigger the callback. The x and y
// arguments specify the location of the upper left corner of the surface
// relative to the upper left corner of the parent surface, in surface-local
// coordinates.
pub fn (proxy &WlShellSurface) set_popup(seat WlSeat, serial u32, parent WlSurface, x i32, y i32, flags u32) ! {
	proxy.conn.request(proxy.id, 6, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
		wayland.ArgValue(wayland.ObjectRef{ id: parent.id }),
		wayland.ArgValue(x),
		wayland.ArgValue(y),
		wayland.ArgValue(flags),
	])!
}

// Map the surface as a maximized surface. If an output parameter is given
// then the surface will be maximized on that output. If the client does not
// specify the output then the compositor will apply its policy - usually
// choosing the output on which the surface has the biggest surface area. The
// compositor will reply with a configure event telling the expected new
// surface size. The operation is completed on the next buffer attach to this
// surface. A maximized surface typically fills the entire output it is bound
// to, except for desktop elements such as panels. This is the main
// difference between a maximized shell surface and a fullscreen shell
// surface. The details depend on the compositor implementation.
pub fn (proxy &WlShellSurface) set_maximized(output ?WlOutput) ! {
	output_id := if value := output { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 7, [wayland.ArgValue(wayland.ObjectRef{ id: output_id })])!
}

// Set a short title for the surface. This string may be used to identify the
// surface in a task bar, window list, or other user interface elements
// provided by the compositor. The string must be encoded in UTF-8.
pub fn (proxy &WlShellSurface) set_title(title string) ! {
	proxy.conn.request(proxy.id, 8, [wayland.ArgValue(title)])!
}

// Set a class for the surface. The surface class identifies the general
// class of applications to which the surface belongs. A common convention is
// to use the file name (or the full path if it is a non-standard location)
// of the application's .desktop file as the class.
pub fn (proxy &WlShellSurface) set_class(class_ string) ! {
	proxy.conn.request(proxy.id, 9, [wayland.ArgValue(class_)])!
}

// wl_shell_surface.resize: values of the wl_shell_surface protocol enum.
// no edge
pub const wl_shell_surface_resize_none = u32(0)
// top edge
pub const wl_shell_surface_resize_top = u32(1)
// bottom edge
pub const wl_shell_surface_resize_bottom = u32(2)
// left edge
pub const wl_shell_surface_resize_left = u32(4)
// top and left edges
pub const wl_shell_surface_resize_top_left = u32(5)
// bottom and left edges
pub const wl_shell_surface_resize_bottom_left = u32(6)
// right edge
pub const wl_shell_surface_resize_right = u32(8)
// top and right edges
pub const wl_shell_surface_resize_top_right = u32(9)
// bottom and right edges
pub const wl_shell_surface_resize_bottom_right = u32(10)

// wl_shell_surface.transient: values of the wl_shell_surface protocol enum.
// do not set keyboard focus
pub const wl_shell_surface_transient_inactive = u32(1)

// wl_shell_surface.fullscreen_method: values of the wl_shell_surface protocol enum.
// no preference, apply default policy
pub const wl_shell_surface_fullscreen_method_default = u32(0)
// scale, preserve the surface's aspect ratio and center on output
pub const wl_shell_surface_fullscreen_method_scale = u32(1)
// switch output mode to the smallest mode that can fit the surface, add
// black borders to compensate size mismatch
pub const wl_shell_surface_fullscreen_method_driver = u32(2)
// no upscaling, center on output and add black borders to compensate size
// mismatch
pub const wl_shell_surface_fullscreen_method_fill = u32(3)

