// WlSeat is a client side proxy for wl_seat.
// A seat is a group of keyboards, pointer and touch devices. This object is
// published as a global during start up, or when such a device is hot
// plugged. A seat typically has a pointer and maintains a keyboard focus and
// a pointer focus.
pub struct WlSeat {
	wayland.Object
}

// wl_seat_proxy wraps an object id in a WlSeat proxy.
pub fn wl_seat_proxy(conn &wayland.Connection, id u32) WlSeat {
	return WlSeat{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_seat'
		}
	}
}

// WlSeatListener receives the events of a wl_seat object.
pub interface WlSeatListener {
	// This is sent on binding to the seat global or whenever a seat gains or
	// loses the pointer, keyboard or touch capabilities. The argument is a
	// capability enum containing the complete set of capabilities this seat has.
	// When the pointer capability is added, a client may create a wl_pointer
	// object using the wl_seat.get_pointer request. This object will receive
	// pointer events until the capability is removed in the future. When the
	// pointer capability is removed, a client should destroy the wl_pointer
	// objects associated with the seat where the capability was removed, using
	// the wl_pointer.release request. No further pointer events will be received
	// on these objects. In some compositors, if a seat regains the pointer
	// capability and a client has a previously obtained wl_pointer object of
	// version 4 or less, that object may start sending pointer events again.
	// This behavior is considered a misinterpretation of the intended behavior
	// and must not be relied upon by the client. wl_pointer objects of version 5
	// or later must not send events if created before the most recent event
	// notifying the client of an added pointer capability. The above behavior
	// also applies to wl_keyboard and wl_touch with the keyboard and touch
	// capabilities, respectively.
mut:
	capabilities(proxy WlSeat, capabilities u32)
	// In a multi-seat configuration the seat name can be used by clients to help
	// identify which physical devices the seat represents. The seat name is a
	// UTF-8 string with no convention defined for its contents. Each name is
	// unique among all wl_seat globals. The name is only guaranteed to be unique
	// for the current compositor instance. The same seat names are used for all
	// clients. Thus, the name can be shared across processes to refer to a
	// specific wl_seat global. The name event is sent after binding to the seat
	// global, and should be sent before announcing capabilities. This event is
	// only sent once per seat object, and the name does not change over the
	// lifetime of the wl_seat global. Compositors may re-use the same seat name
	// if the wl_seat global is destroyed and re-created later.
	name(proxy WlSeat, name string)
}

// NoopWlSeatListener ignores every wl_seat event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlSeatListener {}

pub fn (mut listener NoopWlSeatListener) capabilities(_proxy WlSeat, _capabilities u32) {
}

pub fn (mut listener NoopWlSeatListener) name(_proxy WlSeat, _name string) {
}

struct WlSeatSink {
mut:
	proxy    WlSeat
	listener WlSeatListener = NoopWlSeatListener{}
}

fn (mut s WlSeatSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			capabilities := msg.arg_u32(0)!
			s.listener.capabilities(s.proxy, capabilities)
		}
		1 {
			name := msg.arg_string(0)!
			s.listener.name(s.proxy, name)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_seat events.
pub fn (proxy &WlSeat) set_listener(listener WlSeatListener) ! {
	proxy.conn.set_sink(proxy.id, WlSeatSink{
		proxy:    *proxy
		listener: listener
	})!
}

// The ID provided will be initialized to the wl_pointer interface for this
// seat. This request only takes effect if the seat has the pointer
// capability, or has had the pointer capability in the past. It is a
// protocol violation to issue this request on a seat that has never had the
// pointer capability. The missing_capability error will be sent in this
// case.
pub fn (proxy &WlSeat) get_pointer() !WlPointer {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_pointer'
	}
	proxy.conn.register_object(id_id, 'wl_pointer', &wl_pointer_desc)!
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(wayland.ObjectRef{ id: id_id })])!
	return WlPointer{
		Object: id_object
	}
}

// The ID provided will be initialized to the wl_keyboard interface for this
// seat. This request only takes effect if the seat has the keyboard
// capability, or has had the keyboard capability in the past. It is a
// protocol violation to issue this request on a seat that has never had the
// keyboard capability. The missing_capability error will be sent in this
// case.
pub fn (proxy &WlSeat) get_keyboard() !WlKeyboard {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_keyboard'
	}
	proxy.conn.register_object(id_id, 'wl_keyboard', &wl_keyboard_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: id_id })])!
	return WlKeyboard{
		Object: id_object
	}
}

// The ID provided will be initialized to the wl_touch interface for this
// seat. This request only takes effect if the seat has the touch capability,
// or has had the touch capability in the past. It is a protocol violation to
// issue this request on a seat that has never had the touch capability. The
// missing_capability error will be sent in this case.
pub fn (proxy &WlSeat) get_touch() !WlTouch {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_touch'
	}
	proxy.conn.register_object(id_id, 'wl_touch', &wl_touch_desc)!
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(wayland.ObjectRef{ id: id_id })])!
	return WlTouch{
		Object: id_object
	}
}

// Using this request a client can tell the server that it is not going to
// use the seat object anymore.
pub fn (proxy &WlSeat) release() ! {
	proxy.conn.request(proxy.id, 3, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

