struct WlPointerSink {
mut:
	proxy    WlPointer
	listener WlPointerListener = NoopWlPointerListener{}
}

fn (mut s WlPointerSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			surface_x := msg.arg_fixed(2)!.f64()
			surface_y := msg.arg_fixed(3)!.f64()
			s.listener.enter(s.proxy, serial, surface, surface_x, surface_y)
		}
		1 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			s.listener.leave(s.proxy, serial, surface)
		}
		2 {
			time := msg.arg_u32(0)!
			surface_x := msg.arg_fixed(1)!.f64()
			surface_y := msg.arg_fixed(2)!.f64()
			s.listener.motion(s.proxy, time, surface_x, surface_y)
		}
		3 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			button := msg.arg_u32(2)!
			state := msg.arg_u32(3)!
			s.listener.button(s.proxy, serial, time, button, state)
		}
		4 {
			time := msg.arg_u32(0)!
			axis := msg.arg_u32(1)!
			value_ := msg.arg_fixed(2)!.f64()
			s.listener.axis(s.proxy, time, axis, value_)
		}
		5 {
			s.listener.frame(s.proxy)
		}
		6 {
			axis_source := msg.arg_u32(0)!
			s.listener.axis_source(s.proxy, axis_source)
		}
		7 {
			time := msg.arg_u32(0)!
			axis := msg.arg_u32(1)!
			s.listener.axis_stop(s.proxy, time, axis)
		}
		8 {
			axis := msg.arg_u32(0)!
			discrete := msg.arg_int(1)!
			s.listener.axis_discrete(s.proxy, axis, discrete)
		}
		9 {
			axis := msg.arg_u32(0)!
			value120 := msg.arg_int(1)!
			s.listener.axis_value120(s.proxy, axis, value120)
		}
		10 {
			axis := msg.arg_u32(0)!
			direction := msg.arg_u32(1)!
			s.listener.axis_relative_direction(s.proxy, axis, direction)
		}
		11 {
			surface_x := msg.arg_fixed(0)!.f64()
			surface_y := msg.arg_fixed(1)!.f64()
			s.listener.warp(s.proxy, surface_x, surface_y)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_pointer events.
pub fn (proxy &WlPointer) set_listener(listener WlPointerListener) ! {
	proxy.conn.set_sink(proxy.id, WlPointerSink{
		proxy:    *proxy
		listener: listener
	})!
}

// Set the pointer surface, i.e., the surface that contains the pointer image
// (cursor). This request gives the surface the role of a cursor. If the
// surface already has another role, it raises a protocol error. The cursor
// actually changes only if the pointer focus for this device is one of the
// requesting client's surfaces or the surface parameter is the current
// pointer surface. If there was a previous surface set with this request it
// is replaced. If surface is NULL, the pointer image is hidden. The
// parameters hotspot_x and hotspot_y define the position of the pointer
// surface relative to the pointer location. Its top-left corner is always at
// (x, y) - (hotspot_x, hotspot_y), where (x, y) are the coordinates of the
// pointer location, in surface-local coordinates. On wl_surface.offset
// requests to the pointer surface, hotspot_x and hotspot_y are decremented
// by the x and y parameters passed to the request. The offset must be
// applied by wl_surface.commit as usual. The hotspot can also be updated by
// passing the currently set pointer surface to this request with new values
// for hotspot_x and hotspot_y. The input region is ignored for wl_surfaces
// with the role of a cursor. When the use as a cursor ends, the wl_surface
// is unmapped. The serial parameter must match the latest wl_pointer.enter
// serial number sent to the client. Otherwise the request will be ignored.
pub fn (proxy &WlPointer) set_cursor(serial u32, surface ?WlSurface, hotspot_x i32, hotspot_y i32) ! {
	surface_id := if value := surface { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(serial),
		wayland.ArgValue(wayland.ObjectRef{ id: surface_id }), wayland.ArgValue(hotspot_x),
		wayland.ArgValue(hotspot_y)])!
}

// Using this request a client can tell the server that it is not going to
// use the pointer object anymore. This request destroys the pointer proxy
// object, so clients must not call wl_pointer_destroy() after using this
// request.
pub fn (proxy &WlPointer) release() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// wl_pointer.error: values of the wl_pointer protocol enum.
