}

pub fn (mut listener NoopWlKeyboardListener) leave(_proxy WlKeyboard, _serial u32, _surface WlSurface) {
}

pub fn (mut listener NoopWlKeyboardListener) key(_proxy WlKeyboard, _serial u32, _time u32, _key u32, _state u32) {
}

pub fn (mut listener NoopWlKeyboardListener) modifiers(_proxy WlKeyboard, _serial u32, _mods_depressed u32, _mods_latched u32, _mods_locked u32, _group u32) {
}

pub fn (mut listener NoopWlKeyboardListener) repeat_info(_proxy WlKeyboard, _rate i32, _delay i32) {
}

struct WlKeyboardSink {
mut:
	proxy    WlKeyboard
	listener WlKeyboardListener = NoopWlKeyboardListener{}
}

fn (mut s WlKeyboardSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			format := msg.arg_u32(0)!
			fd := msg.arg_fd(1)!
			size := msg.arg_u32(2)!
			s.listener.keymap(s.proxy, format, fd, size)
		}
		1 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			keys := msg.arg_array(2)!
			s.listener.enter(s.proxy, serial, surface, keys)
		}
		2 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			s.listener.leave(s.proxy, serial, surface)
		}
		3 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			key := msg.arg_u32(2)!
			state := msg.arg_u32(3)!
			s.listener.key(s.proxy, serial, time, key, state)
		}
		4 {
			serial := msg.arg_u32(0)!
			mods_depressed := msg.arg_u32(1)!
			mods_latched := msg.arg_u32(2)!
			mods_locked := msg.arg_u32(3)!
			group := msg.arg_u32(4)!
			s.listener.modifiers(s.proxy, serial, mods_depressed, mods_latched, mods_locked, group)
		}
		5 {
			rate := msg.arg_int(0)!
			delay := msg.arg_int(1)!
			s.listener.repeat_info(s.proxy, rate, delay)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_keyboard events.
pub fn (proxy &WlKeyboard) set_listener(listener WlKeyboardListener) ! {
	proxy.conn.set_sink(proxy.id, WlKeyboardSink{
		proxy:    *proxy
		listener: listener
	})!
}

pub fn (proxy &WlKeyboard) release() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

