struct WlTouchSink {
mut:
	proxy    WlTouch
	listener WlTouchListener = NoopWlTouchListener{}
}

fn (mut s WlTouchSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			surface_id := msg.arg_id(2)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			id := msg.arg_int(3)!
			x := msg.arg_fixed(4)!.f64()
			y := msg.arg_fixed(5)!.f64()
			s.listener.down(s.proxy, serial, time, surface, id, x, y)
		}
		1 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			id := msg.arg_int(2)!
			s.listener.up(s.proxy, serial, time, id)
		}
		2 {
			time := msg.arg_u32(0)!
			id := msg.arg_int(1)!
			x := msg.arg_fixed(2)!.f64()
			y := msg.arg_fixed(3)!.f64()
			s.listener.motion(s.proxy, time, id, x, y)
		}
		3 {
			s.listener.frame(s.proxy)
		}
		4 {
			s.listener.cancel(s.proxy)
		}
		5 {
			id := msg.arg_int(0)!
			major := msg.arg_fixed(1)!.f64()
			minor := msg.arg_fixed(2)!.f64()
			s.listener.shape(s.proxy, id, major, minor)
		}
		6 {
			id := msg.arg_int(0)!
			orientation := msg.arg_fixed(1)!.f64()
			s.listener.orientation(s.proxy, id, orientation)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_touch events.
pub fn (proxy &WlTouch) set_listener(listener WlTouchListener) ! {
	proxy.conn.set_sink(proxy.id, WlTouchSink{
		proxy:    *proxy
		listener: listener
	})!
}

pub fn (proxy &WlTouch) release() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

