struct WlOutputSink {
mut:
	proxy    WlOutput
	listener WlOutputListener = NoopWlOutputListener{}
}

fn (mut s WlOutputSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			x := msg.arg_int(0)!
			y := msg.arg_int(1)!
			physical_width := msg.arg_int(2)!
			physical_height := msg.arg_int(3)!
			subpixel := msg.arg_int(4)!
			make := msg.arg_string(5)!
			model := msg.arg_string(6)!
			transform := msg.arg_int(7)!
			s.listener.geometry(s.proxy, x, y, physical_width, physical_height, subpixel, make, model, transform)
		}
		1 {
			flags := msg.arg_u32(0)!
			width := msg.arg_int(1)!
			height := msg.arg_int(2)!
			refresh := msg.arg_int(3)!
			s.listener.mode(s.proxy, flags, width, height, refresh)
		}
		2 {
			s.listener.done(s.proxy)
		}
		3 {
			factor := msg.arg_int(0)!
			s.listener.scale(s.proxy, factor)
		}
		4 {
			name := msg.arg_string(0)!
			s.listener.name(s.proxy, name)
		}
		5 {
			description := msg.arg_string(0)!
			s.listener.description(s.proxy, description)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_output events.
pub fn (proxy &WlOutput) set_listener(listener WlOutputListener) ! {
	proxy.conn.set_sink(proxy.id, WlOutputSink{
		proxy:    *proxy
		listener: listener
	})!
}

