// Create a sub-surface interface for the given surface, and associate it
// with the given parent surface. This turns a plain wl_surface into a
// sub-surface. The to-be sub-surface must not already have another role, and
// it must not have an existing wl_subsurface object. Otherwise the
// bad_surface protocol error is raised. Adding sub-surfaces to a parent is a
// double-buffered operation on the parent (see wl_surface.commit). The
// effect of adding a sub-surface becomes visible on the next time the state
// of the parent surface is applied. The parent surface must not be one of
// the child surface's descendants, and the parent must be different from the
// child surface, otherwise the bad_parent protocol error is raised. This
// request modifies the behaviour of wl_surface.commit request on the
// sub-surface, see the documentation on wl_subsurface interface.
pub fn (proxy &WlSubcompositor) get_subsurface(surface WlSurface, parent WlSurface) !WlSubsurface {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_subsurface'
	}
	proxy.conn.register_object(id_id, 'wl_subsurface', &wl_subsurface_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: id_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: surface.id }),
		wayland.ArgValue(wayland.ObjectRef{ id: parent.id })])!
	return WlSubsurface{
		Object: id_object
	}
}

