pub fn wl_subsurface_proxy(conn &wayland.Connection, id u32) WlSubsurface {
	return WlSubsurface{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_subsurface'
		}
	}
}

// The sub-surface interface is removed from the wl_surface object that was
// turned into a sub-surface with a wl_subcompositor.get_subsurface request.
// The wl_surface's association to the parent is deleted. The wl_surface is
// unmapped immediately.
pub fn (proxy &WlSubsurface) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// This sets the position of the sub-surface, relative to the parent surface.
// The sub-surface will be moved so that its origin (top left corner pixel)
// will be at the location x, y of the parent surface coordinate system. The
// coordinates are not restricted to the parent surface area. Negative values
// are allowed. The initial position is 0, 0. Position is double-buffered
// state on the parent surface, see wl_subsurface and wl_surface.commit for
