// This sub-surface is taken from the stack, and put back just above the
// reference surface, changing the z-order of the sub-surfaces. The reference
// surface must be one of the sibling surfaces, or the parent surface. Using
// any other surface, including this sub-surface, will cause a protocol
// error. A new sub-surface is initially added as the top-most in the stack
// of its siblings and parent. Z-order is double-buffered state on the parent
// surface, see wl_subsurface and wl_surface.commit for more information.
pub fn (proxy &WlSubsurface) place_above(sibling WlSurface) ! {
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(wayland.ObjectRef{ id: sibling.id })])!
}

// The sub-surface is placed just below the reference surface. See
// wl_subsurface.place_above.
pub fn (proxy &WlSubsurface) place_below(sibling WlSurface) ! {
	proxy.conn.request(proxy.id, 3, [wayland.ArgValue(wayland.ObjectRef{ id: sibling.id })])!
}

// Change the commit behaviour of the sub-surface to synchronized mode. See
// wl_subsurface and wl_surface.commit for more information.
pub fn (proxy &WlSubsurface) set_sync() ! {
	proxy.conn.request(proxy.id, 4, []wayland.ArgValue{})!
}

// Change the commit behaviour of the sub-surface to desynchronized mode. See
// wl_subsurface and wl_surface.commit for more information.
pub fn (proxy &WlSubsurface) set_desync() ! {
	proxy.conn.request(proxy.id, 5, []wayland.ArgValue{})!
}

