		global.version
	} else {
		wl_subcompositor_desc.version
	}
	object := conn.bind_global(global, 'wl_subcompositor', version, &wl_subcompositor_desc)!
	return WlSubcompositor{
		Object: object
	}
}

// bind_wl_fixes binds the wl_fixes global to a typed proxy.
pub fn bind_wl_fixes(conn &wayland.Connection, global wayland.Global) !WlFixes {
	version := if global.version < wl_fixes_desc.version {
		global.version
	} else {
		wl_fixes_desc.version
	}
	object := conn.bind_global(global, 'wl_fixes', version, &wl_fixes_desc)!
	return WlFixes{
		Object: object
	}
}
